{"search":"import data from "./data.json" with { type: "json" };
import { interpret } from "./provider.js";

export async function search(category: "jobs" | "people", query: string, nonce: string) {
  const interpreted = await interpret(category, query, nonce);
  const records = category === "jobs" ? data.jobs : data.people;
  return {
    ids: records.filter((record) => interpreted.ids.includes(record.id)).map((record) => record.id),
    nonce: interpreted.nonce,
  };
}
","provider":"import config from "./provider.json" with { type: "json" };

export async function interpret(
  category: string,
  query: string,
  nonce: string,
): Promise<{ ids: string[]; nonce: string }> {
  // The provider answers POSTs on any path except "/", which is only a readiness page.
  const response = await fetch(new URL("/search", config.url), {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ category, query, nonce }),
  });
  if (!response.ok) throw new Error(`Search provider unavailable (${response.status})`);
  const body = (await response.json()) as { ids?: unknown; nonce?: unknown };
  if (!Array.isArray(body.ids) || typeof body.nonce !== "string")
    throw new Error("Search provider returned an invalid response");
  return { ids: body.ids.filter((id): id is string => typeof id === "string"), nonce: body.nonce };
}
"}

